export function findStampIcon(emoji: string | null | undefined): StampIcon {
  const wanted = emoji?.trim();
  return (
    STAMP_ICONS.find((icon) => icon.emoji === wanted) ??
    STAMP_ICONS.find((icon) => icon.emoji === DEFAULT_STAMP_EMOJI)!
  );
}
